#define RHO_LOG_SOURCE_NOISE_NO_MAIN
#include "test_rho_log_source_noise.cpp"
#include "z4c/hyperboloidal/supported_rho_log_derivative.hpp"
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int status=0;try{
  if(argc!=2)throw std::invalid_argument("usage actual initial.dat");auto grid=MakeGrid();const auto initial=ReadInitial(argv[1],grid);V stored(2*initial.size());for(size_t p=0;p<initial.size();++p){stored[2*p]=std::log(initial[p].chi);stored[2*p+1]=std::log(initial[p].alpha)-std::log(Chart(grid.geometry[p].x,1).reference.value);}h::PuncturePosition point;h::PunctureLogPlans base(grid,point);std::cout<<std::setprecision(17);SourceNoiseStats stats[2];size_t ready=0;std::map<size_t,size_t>counts;
  for(const auto &row:base.rows){const size_t p=row.active;const auto &x=grid.geometry[p].x;const auto nearest=Nearest(grid,p,256);std::vector<h::SupportedRhoLogDerivative::Point>nodes;for(const auto &d:nearest){const auto &y=grid.geometry[d.second].x;nodes.push_back({y[0],y[1],y[2]});}h::SupportedRhoLogDerivative fit;
    if(fit.Build({x[0],x[1],x[2]},nodes,Spacing(grid,p),point)){++ready;++counts[fit.selected_count()];auto selected=row;selected.donors.clear();for(size_t i=0;i<fit.selected_count();++i)selected.donors.push_back(nearest[i].second);SourceNoise("supported_rho",fit,selected,grid,initial,stored,stats[1],true);}else std::cout<<"{\"phase\":\"unsupported\",\"point\":"<<p<<",\"status\":\""<<fit.diagnostics().status<<"\"}\n";
    SourceNoise("base125",row.plan,row,grid,initial,stored,stats[0],true);}
  std::cout<<"{\"phase\":\"summary\",\"selected_rows\":"<<base.rows.size()<<",\"supported_ready\":"<<ready<<",\"support_counts\":{";bool first=true;for(const auto &x:counts){if(!first)std::cout<<',';first=false;std::cout<<'"'<<x.first<<"\":"<<x.second;}std::cout<<"},\"base125\":";stats[0].Print();std::cout<<",\"supported_rho\":";stats[1].Print();std::cout<<",\"all_changed_rows_included\":"<<(ready==base.rows.size())<<",\"full58columns_retained\":true,\"caps_unchanged_16_32_64\":true,\"outside_selected_operator_unchanged\":true,\"principal_lapse_is_not_complete_RHS\":true,\"production_adopted\":false}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
